import { createProductController } from './CatalogueModule';
import { createHttpApp } from './HttpApp';
import { createOrderController } from './OrderModule';
import { createInMemoryPersistence } from './Persistence';
import { RandomIdGenerator } from './RandomIdGenerator';
import { SystemClock } from './SystemClock';

const port = Number(process.env['PORT'] ?? 3000);

const persistence = createInMemoryPersistence();
const app = createHttpApp(
  createOrderController(persistence, new RandomIdGenerator(), new SystemClock()),
  createProductController(persistence),
);

app.listen(port, () => {
  console.log(`Order fulfilment API listening on http://localhost:${port}`);
});

